impl<S: gx::Slots, T: gx::Coef> gx::Transform<Point<S, T>> for gx::Unit<Translator<(), T>> {
    type Output = Point<S, T>;
    #[inline(always)]
    fn transform(self, x: Point<S, T>) -> Point<S, T> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[0].mul_add(v[0], -T::from_i64(1));
            T::check_unit(&[u1]);
        }
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[0] * xv[2];
        let t2 = xv[0] * t0;
        let t3 = v[2] * t1;
        let t5 = v[1] * t1;
        let t6 = xv[2] * t0;
        let t8 = (-t3).mul_add(T::from_i64(2), t2);
        let t9 = t5 * T::from_i64(2);
        let t10 = xv[1].mul_add(t0, t9);
            return Point { c: gx::slots::from_values::<S, T, 3>([t8, t10, t6]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[0] * v[2];
        let m2 = v[0] * v[1];
        let m3 = m1 * T::from_i64(2);
        let m4 = -m3;
        let m5 = m2 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Point { c: [(x[0].scale(m0) + x[2].scale(m4)).0, (x[1].scale(m0) + x[2].scale(m5)).0, (x[2].scale(m0)).0] }
    }
}

